modes.detail:
// ============ 邻接矩阵长什么样 ============
//
// 一个二维数组 G[nv][nv]，G[i][j] 表示从 i 到 j 有没有边：
//
//             0  1  2  3
//        0 [  0  1  0  1 ]
//        1 [  1  0  1  0 ]
//        2 [  0  1  0  1 ]
//        3 [  1  0  1  0 ]
//
// 特点：
//
//   · 判断"i 和 j 之间有没有边"只要**一次数组访问**，O(1) —— 这是它最大的优点
//   · 无向图的矩阵是**对称**的（G[i][j] == G[j][i]），所以有一半空间是浪费的
//   · 不管图里实际有多少条边，都要占 n² 个格子
//
// 所以邻接矩阵适合**稠密图**（边数接近 n²）：反正都要占这么多空间，
// 换个 O(1) 的判断速度很划算。
//
// ============ 邻接表长什么样 ============
//
// 每个顶点挂一条链表，串着和它相邻的所有顶点：
//
//        0 → [1] → [3]
//        1 → [0] → [2]
//        2 → [1] → [3]
//        3 → [0] → [2]
//
// 特点：
//
//   · 空间是 O(n + e)：**有多少边就占多少空间**，稀疏图下省得多
//   · 判断"i 和 j 有没有边"要顺着 i 的链表找，最坏 O(n)
//   · 想列举"i 的所有邻居"很自然 —— 遍历链表就行
//
// 所以邻接表适合**稀疏图**（实际中的图绝大多数都是稀疏的）。
//
// ============ 怎么选 ============
//
//   稠密图、经常要判断两点是否相邻  →  邻接矩阵
//   稀疏图、经常要遍历某个点的邻居  →  邻接表
//
// 后面的 DFS、BFS、Dijkstra 用两种都能写。本课程统一用矩阵，
// 因为它写起来短、看起来直观；但要知道**工程里邻接表更常用**。

// 最多多少个顶点
#define MAXV 100

// 表示"没有边"的特殊值
// 用一个大数而不是 0，是为了把"没有边"和"权值为 0 的边"区分开。
// 如果图不带权，只是 0/1，那用 0 表示无边也没问题。
#define INF 65535

// 邻接矩阵存图
typedef struct
{
// 顶点数
    int nv;
// 边数
    int ne;
// 矩阵：g[i][j] 为 0 表示无边，非 0 表示有边（或权值）
    int g[MAXV][MAXV];
} MGraph;

// 邻接表的边结点
typedef struct AdjNode
{
// 这个邻居的顶点编号
    int adjv;
// 边的权值（无权图可以忽略）
    int weight;
// 下一个邻居
    struct AdjNode *next;
} AdjNode, *AdjList;

// 邻接表存图
typedef struct
{
// 每个顶点一条链表，head[i] 是顶点 i 的邻居链表头
    AdjList head[MAXV];
// 顶点数
    int nv;
// 边数
    int ne;
} LGraph;

// 状态码
#define OK 1
#define ERROR 0
typedef int Status;

