modes.detail:
// ============ 建图的步骤 ============
//
//   ① 把整个矩阵清零（表示"什么边都没有"）
//   ② 读入每一条边 (u, v)，把 g[u][v] 和 g[v][u] 都置 1
//
// 第 ② 步的两个格子都要填 —— 因为是无向图。
//
// **只填一半是最常见的错误**：图看起来能跑，但只能"从 u 走到 v"，
// 不能反过来走。遍历的时候会得到莫名其妙的结果。
//
// 有向图就只填 g[u][v] 一个格子，这正是有向和无向在存储上的唯一区别。
//
// ============ 顶点编号 ============
//
// 图里的顶点通常编号 0..n-1（或者 1..n）。这里统一用 0 起始，
// 这样可以直接当数组下标用，不用到处做 +1/-1 的转换。

// 用边表建一个邻接矩阵存的无向图
// edges 每条边两个端点，edgeCount 是边数
void CreateMatrix(MGraph *G, int nv, const int edges[][2], int edgeCount)
{
// 循环用
    int i, j;

// 记下顶点数
    G->nv = nv;
// 记下边数
    G->ne = edgeCount;

// ① 矩阵清零
    for (i = 0; i < nv; i++)
    {
        for (j = 0; j < nv; j++)
        {
            G->g[i][j] = 0;
        }
    }

// ② 逐条边填格子
    for (i = 0; i < edgeCount; i++)
    {
// 取出两个端点
        int u = edges[i][0];
        int v = edges[i][1];

// 无向图：两个方向都要填
// 有向图这里只写 G->g[u][v] = 1 就够了。
        G->g[u][v] = 1;
        G->g[v][u] = 1;
    }
}

// 判断 i 和 j 之间有没有边
// 邻接矩阵最大的优势就是这一句 —— O(1)。
int HasEdge(MGraph *G, int i, int j)
{
// 直接查表
    return G->g[i][j] != 0;
}

