modes.detail:
// ============ 建邻接表 ============
//
//   ① 把所有链表头置空
//   ② 读入边 (u, v)：在 u 的链表里插一个"v 号邻居"，在 v 的链表里插一个"u 号邻居"
//
// 又是"两个方向都要插" —— 和邻接矩阵一样。
//
// ============ 头插法 ============
//
// 插件点用**头插**（插在链表最前面），因为：
//
//   · 不用找尾，O(1) 就完成
//   · 链表里的顺序本来就不重要（邻居之间无先后）
//
// 代价是链表里的顺序和插边顺序**相反**。如果做题时要求输出"按编号从小到大"，
// 就得先收集再排序，或者改用尾插。
//
// ============ 空间对比 ============
//
// 还是 4 个顶点 4 条边的那个图：
//
//   邻接矩阵：4×4 = 16 个 int
//   邻接表：  4 个链表头 + 4×2 = 8 个边结点
//
// 顶点一多差距就惊人了。1000 个顶点、2000 条边：
//
//   邻接矩阵：1000×1000 = 100 万个格子
//   邻接表：  1000 + 4000 = 5000 个结点
//
// 差 200 倍。这就是稀疏图必须用邻接表的原因。

// 在顶点 u 的链表头部插一个邻居 v
// 单独抽出来是因为要调用两次（u 那边一次、v 那边一次）。
void AddEdgeNode(LGraph *G, int u, int v, int w)
{
// 造一个边结点
    AdjNode *node = (AdjNode *)malloc(sizeof(AdjNode));
// 分配失败要挡住
    if (node == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }

// 填内容
    node->adjv = v;
    node->weight = w;

// 头插：新结点指向原来的第一个
    node->next = G->head[u];

// 链表头改成新结点
    G->head[u] = node;
}

// 用边表建一个邻接表存的无向图
void CreateList(LGraph *G, int nv, const int edges[][2], int edgeCount)
{
// 循环用
    int i;

// 记下规模
    G->nv = nv;
    G->ne = edgeCount;

// ① 所有链表头置空
    for (i = 0; i < nv; i++)
    {
        G->head[i] = NULL;
    }

// ② 逐条边插两个结点
    for (i = 0; i < edgeCount; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];

// u 的邻居里加上 v
        AddEdgeNode(G, u, v, 1);
// v 的邻居里加上 u —— 别漏
        AddEdgeNode(G, v, u, 1);
    }
}

// 判断 i 和 j 之间有没有边
// 邻接表在这里比矩阵慢：要顺着链表找，最坏 O(n)。
int HasEdgeList(LGraph *G, int i, int j)
{
// 顺着 i 的链表找
    AdjNode *p = G->head[i];

    while (p != NULL)
    {
// 找到了
        if (p->adjv == j)
        {
            return 1;
        }
// 下一个
        p = p->next;
    }

// 找完了也没有
    return 0;
}

// 数一数顶点 i 有几个邻居（也就是它的度）
int DegreeOf(LGraph *G, int i)
{
// 遍历计数
    AdjNode *p = G->head[i];
    int count = 0;

    while (p != NULL)
    {
        count++;
        p = p->next;
    }

    return count;
}

