#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

#define MAXV 100

#define INF 65535

typedef struct
{
    int nv;
    int ne;
    int g[MAXV][MAXV];
} MGraph;

typedef struct AdjNode
{
    int adjv;
    int weight;
    struct AdjNode *next;
} AdjNode, *AdjList;

typedef struct
{
    AdjList head[MAXV];
    int nv;
    int ne;
} LGraph;

#define OK 1
#define ERROR 0
typedef int Status;

/* ======== [已给出] 模块 06 FreeList ======== */
void FreeList(LGraph *G)
{
    int i;
    AdjNode *p, *q;

    for (i = 0; i < G->nv; i++)
    {
        p = G->head[i];

        while (p != NULL)
        {
            q = p->next;
            free(p);
            p = q;
        }

        G->head[i] = NULL;
    }
}

/* ====================================================================
 *  轮到你了：模块 03  CreateList
 *  作用：每个顶点一条链表，插边就是往两条链表里各插一个结点。
 *  提示：先写函数签名，再写循环定位，最后写指针操作。
 *  写完按 Ctrl + Enter 编译运行，点"对比"看与参考实现的差异。
 * ==================================================================== */



