    LGraph L;
    int i;
    AdjNode *p;

    CreateList(&L, 4, edges, 4);

    printf("顶点数 %d，边数 %d\n\n", L.nv, L.ne);

    for (i = 0; i < 4; i++)
    {
        printf("  %d 的邻居: ", i);
        p = L.head[i];
        while (p != NULL)
