#include <stdio.h>
#include <stdlib.h>

/* ======== [已给出] 模块 01 typedef ======== */

#define MAXV 100

#define INF 65535

typedef struct
{
    int nv;
    int ne;
    int g[MAXV][MAXV];
} MGraph;

typedef struct AdjNode
{
    int adjv;
    int weight;
    struct AdjNode *next;
} AdjNode, *AdjList;

typedef struct
{
    AdjList head[MAXV];
    int nv;
    int ne;
} LGraph;

#define OK 1
#define ERROR 0
typedef int Status;

/* ======== [已给出] 模块 03 CreateList ======== */

void AddEdgeNode(LGraph *G, int u, int v, int w)
{
    AdjNode *node = (AdjNode *)malloc(sizeof(AdjNode));
    if (node == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }

    node->adjv = v;
    node->weight = w;

    node->next = G->head[u];

    G->head[u] = node;
}

void CreateList(LGraph *G, int nv, const int edges[][2], int edgeCount)
{
    int i;

    G->nv = nv;
    G->ne = edgeCount;

    for (i = 0; i < nv; i++)
    {
        G->head[i] = NULL;
    }

    for (i = 0; i < edgeCount; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];

        AddEdgeNode(G, u, v, 1);
        AddEdgeNode(G, v, u, 1);
    }
}

int HasEdgeList(LGraph *G, int i, int j)
{
    AdjNode *p = G->head[i];

    while (p != NULL)
    {
        if (p->adjv == j)
        {
            return 1;
        }
        p = p->next;
    }

    return 0;
}

int DegreeOf(LGraph *G, int i)
{
    AdjNode *p = G->head[i];
    int count = 0;

    while (p != NULL)
    {
        count++;
        p = p->next;
    }

    return count;
}

/* ======== [已给出] 模块 06 FreeList ======== */
void FreeList(LGraph *G)
{
    int i;
    AdjNode *p, *q;

    for (i = 0; i < G->nv; i++)
    {
        p = G->head[i];

        while (p != NULL)
        {
            q = p->next;
            free(p);
            p = q;
        }

        G->head[i] = NULL;
    }
}

