modes.detail:
// 每个边结点都是单独 malloc 的，要一个个放。
// 注意**先记住 next 再 free 当前结点** —— 顺序反了就取不到下一个了。
void FreeList(LGraph *G)
{
// 循环用
    int i;
// 当前结点和下一个
    AdjNode *p, *q;

    for (i = 0; i < G->nv; i++)
    {
        p = G->head[i];

        while (p != NULL)
        {
// 先记住下一个
            q = p->next;
// 再释放当前
            free(p);
// 往后走
            p = q;
        }

// 链表头置空，防止变成野指针
        G->head[i] = NULL;
    }
}

