}


// 在顶点 u 的链表头部插一个邻居 v
void AddEdgeNode(LGraph *G, int u, int v, int w)
{
// 造一个边结点
    AdjNode *node = (AdjNode *)malloc(sizeof(AdjNode));
// 分配失败要挡住
    if (node == NULL)
    {
        printf("内存分配失败\n");
        exit(1);
    }

// 填内容
    node->adjv = v;
    node->weight = w;

// 头插：新结点指向原来的第一个
    node->next = G->head[u];

// 链表头改成新结点
    G->head[u] = node;
}

// 用边表建一个邻接表存的无向图
void CreateList(LGraph *G, int nv, const int edges[][2], int edgeCount)
{
// 循环用
    int i;

// 记下规模
    G->nv = nv;
    G->ne = edgeCount;

// ① 所有链表头置空
    for (i = 0; i < nv; i++)
    {
        G->head[i] = NULL;
    }

// ② 逐条边插两个结点
    for (i = 0; i < edgeCount; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];

// u 的邻居里加上 v
        AddEdgeNode(G, u, v, 1);
// v 的邻居里加上 u —— 别漏
        AddEdgeNode(G, v, u, 1);
    }
}

// 判断 i 和 j 之间有没有边
int HasEdgeList(LGraph *G, int i, int j)
{
// 顺着 i 的链表找
    AdjNode *p = G->head[i];

    while (p != NULL)
    {
// 找到了
        if (p->adjv == j)
        {
            return 1;
        }
// 下一个
        p = p->next;
    }

// 找完了也没有
    return 0;
}

// 数一数顶点 i 有几个邻居（也就是它的度）
int DegreeOf(LGraph *G, int i)
{
// 遍历计数
    AdjNode *p = G->head[i];
    int count = 0;

    while (p != NULL)
    {
        count++;
        p = p->next;
    }

    return count;
}

void PrintMatrix(MGraph *G)
{
// 循环用
    int i, j;
// 对称性检查
    int symmetric = 1;

// 打印列号
    printf("     ");
    for (j = 0; j < G->nv; j++)
    {
        printf("%3d", j);
    }
    printf("\n");

// 逐行打印
    for (i = 0; i < G->nv; i++)
    {
        printf("%3d [", i);

        for (j = 0; j < G->nv; j++)
        {
            printf("%3d", G->g[i][j]);

// 顺便检查对称
            if (G->g[i][j] != G->g[j][i])
            {
                symmetric = 0;
            }
        }
        printf(" ]\n");
    }

// 报告对称性
    printf("\n无向图的邻接矩阵一定对称: %s\n", symmetric ? "是（检查通过）" : "不是（有问题）");
}


// 打印邻接表
void PrintList(LGraph *G)
{
// 循环用
    int i;
// 遍历指针
    AdjNode *p;

    for (i = 0; i < G->nv; i++)
    {
        printf("%2d → ", i);
        p = G->head[i];

        while (p != NULL)
        {
            printf("[%d] ", p->adjv);
            p = p->next;
        }
        printf("(度 = %d)\n", DegreeOf(G, i));
    }
}

void FreeList(LGraph *G)
{
// 循环用
    int i;
// 当前结点和下一个
    AdjNode *p, *q;

    for (i = 0; i < G->nv; i++)
    {
        p = G->head[i];

        while (p != NULL)
        {
// 先记住下一个
            q = p->next;
// 再释放当前
            free(p);
// 往后走
            p = q;
        }

// 链表头置空，防止变成野指针
        G->head[i] = NULL;
    }
}


// 主函数
int main(void)
{
// 图：0-1，1-2，2-3，3-0（一个正方形）
    static const int edges[][2] = { { 0, 1 }, { 1, 2 }, { 2, 3 }, { 3, 0 } };
// 顶点数
    int nv = 4;
// 边数
    int ne = 4;
// 邻接矩阵
    MGraph G;
// 邻接表
    LGraph L;
// 循环用
    int i;

// 打印图的样子
    printf("图：0-1，1-2，2-3，3-0\n");
    printf("        0 ── 1\n");
    printf("        │    │\n");
    printf("        3 ── 2\n\n");

// 建矩阵存法
    CreateMatrix(&G, nv, edges, ne);
    printf("=== 邻接矩阵 ===\n");
    PrintMatrix(&G);

// 建表存法
    CreateList(&L, nv, edges, ne);
    printf("\n=== 邻接表 ===\n");
    PrintList(&L);

// 对比两种查边的速度
    printf("\n=== 查边对比 ===\n");
    printf("查 0 和 2 有没有边：\n");
    printf("  邻接矩阵 %s（一次数组访问）\n", HasEdge(&G, 0, 2) ? "有" : "无");
    printf("  邻接表   %s（要顺着 0 的链表找）\n", HasEdgeList(&L, 0, 2) ? "有" : "无");
    printf("查 0 和 1 有没有边：\n");
    printf("  邻接矩阵 %s\n", HasEdge(&G, 0, 1) ? "有" : "无");
    printf("  邻接表   %s\n", HasEdgeList(&L, 0, 1) ? "有" : "无");

// 数度数
    printf("\n=== 每个顶点的度 ===\n");
    for (i = 0; i < nv; i++)
    {
        printf("  顶点 %d 的度 = %d\n", i, DegreeOf(&L, i));
    }
    printf("（无向图里每个点的度就是它邻居的个数，也就是它在链表里的结点数）\n");

// 空间对比
    printf("\n=== 空间对比 ===\n");
    printf("  邻接矩阵：%d × %d = %d 个 int\n", nv, nv, nv * nv);
    printf("  邻接表  ：%d 个链表头 + %d 个边结点\n", nv, 2 * ne);
    printf("（顶点多了差距会非常明显：1000 个点时是 100 万 对 5000）\n");

// 释放邻接表
    FreeList(&L);
    printf("\n邻接表已释放（矩阵不用释放，它是固定数组）\n");

// 正常结束
    return 0;
}

